import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Muhtasari wa Itifaki ya Kichunguzi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/84-考古协议总纲.md","filePath":"sw/84-考古协议总纲.md","lastUpdated":1789183869000}'),t={name:"sw/84-考古协议总纲.md"};function h(e,a,o,w,y,l){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="muhtasari-wa-itifaki-ya-kichunguzi" tabindex="-1">Muhtasari wa Itifaki ya Kichunguzi <a class="header-anchor" href="#muhtasari-wa-itifaki-ya-kichunguzi" aria-label="Permalink to &quot;Muhtasari wa Itifaki ya Kichunguzi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>84</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Itifaki ya kichunguzi, kioo cha nakala, nafasi iliyotengwa, kurudisha maarifa tu, uchafuzi wa chini</td></tr></tbody></table><h2 id="_1-nafasi-na-malengo-ya-itifaki-ya-kichunguzi" tabindex="-1">1. Nafasi na Malengo ya Itifaki ya Kichunguzi <a class="header-anchor" href="#_1-nafasi-na-malengo-ya-itifaki-ya-kichunguzi" aria-label="Permalink to &quot;1. Nafasi na Malengo ya Itifaki ya Kichunguzi&quot;">​</a></h2><p>Kichunguzi cha kati ya ndege na kichunguzi cha kurudi nyuma kwa wakati ni njia muhimu kwa ustaarabu wa symbiosis wa nanga kupata maarifa ya kihistoria na kuelewa mageuzi ya ulimwengu. Walakini, hatua yenyewe ya kichunguzi ina hatari ya juu — kuingia moja kwa moja kwenye ndege ya lengwa au kipindi cha lengwa kufanya uchimbaji wa kichunguzi, kunaweza kusababisha uharibifu wa kimwili, usumbufu wa sheria, na uchafuzi wa kitamaduni kwa kipengele cha lengwa. Ili kurekebisha hatua ya kichunguzi na kupunguza hatari za kichunguzi, Hengyuanzhou imeandaa &quot;Muhtasari wa Itifaki ya Kichunguzi&quot; uliounganishwa, kama kanuni ya msingi ya uendeshaji ya shughuli zote za kichunguzi cha kati ya ndege na kurudi nyuma kwa wakati.</p><p>Lengo la msingi la itifaki ya kichunguzi linaweza kufupishwa katika &quot;viwango vitatu vya juu zaidi&quot;: kupata maarifa kamili ya kihistoria kwa kiwango cha juu zaidi, kupunguza kuingilia kazi na uharibifu kwa kipengele cha lengwa kwa kiwango cha chini zaidi, na kuhakikisha usalama wa wafanyakazi wa kichunguzi kwa kiwango cha juu zaidi. Kuna mvutano wa ndani kati ya malengo haya matatu — ukamilifu wa kupata maarifa mara nyingi unahitaji mawasiliano ya kina zaidi, wakati kanuni ya kuingilia kazi kwa chini pia inapunguza uzoefu wa mawasiliano. Muundo wote wa sheria ya itifaki ya kichunguzi ni kwa ajili ya kupata usawa bora kati ya hizi tatu.</p><p>Itifaki ya kichunguzi inatumika katika mazingira yafuatayo: uchunguzi wa kichunguzi wa mabaki ya ustaarabu katika ndege isiyojulikana, urejesho wa kihistoria wa ustaarabu uliopotea kupitia kurudi nyuma kwa wakati, kichunguzi cha kina cha kiwango cha sheria kwa mabaki ya kale ya ndege ya mwenyewe, na uchimbaji wa uokoaji wa mabaki ya kale katika ndege yenye sheria zilizovunjika.</p><h2 id="_2-vitu-vitatu-vya-mpango-wa-kichunguzi" tabindex="-1">2. Vitu Vitatu vya Mpango wa Kichunguzi <a class="header-anchor" href="#_2-vitu-vitatu-vya-mpango-wa-kichunguzi" aria-label="Permalink to &quot;2. Vitu Vitatu vya Mpango wa Kichunguzi&quot;">​</a></h2><p>Mpango wa kawaida wa kichunguzi wa Hengyuanzhou unajengwa na vitu vitatu vya msingi, vinayoitwa &quot;vitu vitatu vya kichunguzi&quot;:</p><h3 id="_2-1-kioo-cha-nakala" tabindex="-1">2.1 Kioo cha Nakala <a class="header-anchor" href="#_2-1-kioo-cha-nakala" aria-label="Permalink to &quot;2.1 Kioo cha Nakala&quot;">​</a></h3><p>Kioo cha nakala ni kifaa cha nakala cha usahihi wa juu kinachotegemea sheria za kisheria za nafasi, kinachoweza kufanya nakala kamili ya 1:1 ya muundo wa vifaa, nishati, na taarifa ndani ya eneo la lengwa bila kugusa kipengele cha asili. Kanuni ya kufanya kazi ya kioo cha nakala ni kupitia sheria za nafasi kupitia skana hali zote za chembe na usambazaji wa uwanja wa nishati wa eneo la lengwa, kisha kujenga tena nakala kamili inayofanana kabisa ndani ya nafasi iliyotengwa. Mchakato wa nakala hubadilisha hali yoyote ya kipengele cha asili, kwa hivyo hausababishi kuingilia kazi yoyote ya kimwili kwenye eneo la kichunguzi.</p><p>Usahihi wa nakala wa kioo cha nakala unafika kiwango cha chini ya atomu, na unaweza kurejesha kabisa muundo wa vifaa, mabaki ya nishati, alama za fahari, na hata vipande vya mnyororo wa sababu ndani ya eneo la lengwa. Upeo wa nakala unaweza kuzunguliwa kulingana na mahitaji ya kichunguzi, kitengo cha chini cha nakala ni kipengele kimoja cha kichunguzi, na kikubwa kinaweza kufunikia kikundi kamili cha mabaki. Wakati wa nakala unategemea ukubwa wa upeo wa nakala, nakala ya kipengele kimoja cha kichunguzi kwa kawaida inakamilika ndani ya dakika chache, na nakala ya kikundi kikubwa cha mabaki inaweza kuchukua siku kadhaa.</p><h3 id="_2-2-nafasi-iliyotengwa" tabindex="-1">2.2 Nafasi Iliyotengwa <a class="header-anchor" href="#_2-2-nafasi-iliyotengwa" aria-label="Permalink to &quot;2.2 Nafasi Iliyotengwa&quot;">​</a></h3><p>Nafasi iliyotengwa ni eneo la sheria la kujitegemea lililojengwa kupitia teknolojia ya usimamizi wa sheria za nafasi, inayotumika kubeba nakala za kichunguzi zinazotengenezwa na kioo cha nakala, na kama mahali pa kazi kwa wafanyakazi wa kichunguzi. Nafasi iliyotengwa na ndege ya lengwa au kipindi cha lengwa zimetengwa na kizuizi kamili cha sheria, na kuhakikisha kwamba uendeshaji wa kichunguzi hausababishi athari yoyote ya kinyume kwa lengo la asili.</p><p>Vigezo vya sheria ndani ya nafasi iliyotengwa vinaweza kuzoboiwa kulingana na mahitaji ya kichunguzi, ikiwa ni pamoja na: kuiga vigezo vya mazingira vya ndege ya lengwa ili kuhakikisha utulivu wa nakala ya vifaa vya kichunguzi, kuweka uwanja maalum wa sheria ya uchambuzi ili kusaidia utafiti wa kichunguzi, na kujenga uwanja mkali wa kuzuia uchafuzi ili kuzuia utiririko wa nishati na fahari ya wafanyakazi wa kichunguzi. Ukubwa wa nafasi iliyotengwa unaweza kupanuliwa kulingana na mahitaji, na kikubwa kinaweza kubeba nakala kamili ya mabaki ya kiwango cha mji.</p><h3 id="_2-3-kurudisha-maarifa-tu" tabindex="-1">2.3 Kurudisha Maarifa Tu <a class="header-anchor" href="#_2-3-kurudisha-maarifa-tu" aria-label="Permalink to &quot;2.3 Kurudisha Maarifa Tu&quot;">​</a></h3><p>&quot;Kurudisha maarifa tu&quot; ni moja ya kanuni za msingi za itifaki ya kichunguzi, inayomaanisha kwamba kinachopatikana kutoka kwa kipengele cha lengwa wakati wa mchakato wa kichunguzi ni maarifa na taarifa za kihisi tu, na haifai kurudisha vifaa, nishati, au viumbe hai vyovyote. Baada ya wafanyakazi wa kichunguzi kufanya utafiti wa nakala ndani ya nafasi iliyotengwa, wanaweza tu kurudisha hitimisho la utafiti, rekodi za data, na ripoti za uchambuzi kwenye ndege ya mwenyewe katika namna ya taarifa safi; nakala yenyewe na sampuli zozote za vifaa zilizochorwa kutoka kwa nakala lazima ziharibiwe ndani ya nafasi iliyotengwa.</p><p>Lengo la msingi la kanuni hii ni kuzuia uchafuzi wa kati ya ndege na usumbufu wa mstari wa wakati. Hata chembe ya vumbi iliyochorwa kutoka kwa nakala inaweza kubeba taarifa za sheria za ndege ya lengwa, na mara moja inapoingia kwenye mtandao wa sheria wa ndege ya mwenyewe, inaweza kusababisha mmenuko wa sababu wa kutokitarajiwa. Kwa hivyo, &quot;kurudisha maarifa tu&quot; sio pendekezo la uendeshaji linaloweza kubadilishwana, bali ni kanuni ngumu yenye nguvu ya kisheria ya kulazimisha.</p><h2 id="_3-mchakato-wa-kawaida-wa-uendeshaji-wa-kichunguzi" tabindex="-1">3. Mchakato wa Kawaida wa Uendeshaji wa Kichunguzi <a class="header-anchor" href="#_3-mchakato-wa-kawaida-wa-uendeshaji-wa-kichunguzi" aria-label="Permalink to &quot;3. Mchakato wa Kawaida wa Uendeshaji wa Kichunguzi&quot;">​</a></h2><p>Uendeshaji kamili wa kichunguzi cha kati ya ndege au kurudi nyuma kwa wakati unafuata mchakato wa kawaida ufuatao:</p><table tabindex="0"><thead><tr><th>Hatua</th><th>Maudhui ya Uendeshaji</th><th>Upande wa Wajibu</th><th>Marejeo ya Muda</th></tr></thead><tbody><tr><td>Hatua ya 1: Uidhinishaji wa Mradi</td><td>Kuwasilisha ombi la kichunguzi, kufafanua malengo, upeo, na mpango wa kichunguzi, kupata ruhusa ya kuvuka ya Kiwango A au ruhusa ya kurudi nyuma</td><td>Timu ya kichunguzi→Ofisi ya Usimamizi wa Ndege/Kamati ya Sheria za Wakati</td><td>Siku 7-30</td></tr><tr><td>Hatua ya 2: Uchunguzi awali</td><td>Kulingana na miongozo ya &quot;uchunguzi awali, kisha kuingilia kazi kwa mdogo&quot;, kufanya uchunguzi safi kwa muda usio chini ya masaa 72 kwenye eneo la lengwa</td><td>Timu ya kichunguzi</td><td>Zaidi ya masaa 72</td></tr><tr><td>Hatua ya 3: Utekelezaji wa Kioo cha Nakala</td><td>Kutekeleza kioo cha nakala katika eneo salama karibu na eneo la lengwa, kuweka upeo wa nakala na vigezo vya usahihi</td><td>Timu ya teknolojia</td><td>Masaa machache hadi siku kadhaa</td></tr><tr><td>Hatua ya 4: Uundaji wa Nakala</td><td>Kuanzisha kioo cha nakala, kunakili kamili eneo la lengwa kwenye nafasi iliyotengwa iliyojengwa mapema</td><td>Timu ya teknolojia</td><td>Dakika chache hadi siku kadhaa</td></tr><tr><td>Hatua ya 5: Kichunguzi katika Nafasi Iliyotengwa</td><td>Wafanyakazi wa kichunguzi wanaingia ndani ya nafasi iliyotengwa, wanafanya uchimbaji, uchambuzi, na utafiti wa kila aina wa nakala</td><td>Timu ya kichunguzi</td><td>Siku kadhaa hadi miaka kadhaa</td></tr><tr><td>Hatua ya 6: Kupanga Maarifa</td><td>Kupanga matokeo ya kichunguzi, kuunda ripoti za utafiti na hifadhi ya data ya maarifa, kuhakikisha kuwa matokeo yote ni katika namna ya taarifa safi</td><td>Timu ya kichunguzi</td><td>Siku kadhaa hadi miezi kadhaa</td></tr><tr><td>Hatua ya 7: Kutoa na Kuharibu</td><td>Wafanyakazi wa kichunguzi wanatoka ndani ya nafasi iliyotengwa, wanaharibu vifaa vyote vya nakala na mabaki ya nishati, wanafunga nafasi iliyotengwa</td><td>Timu ya teknolojia+timu ya ufuatiliaji</td><td>Masaa machache</td></tr><tr><td>Hatua ya 8: Ukaguzi wa Baadaye</td><td>Kuwasilisha ripoti kamili ya kichunguzi, kupokea ukaguzi wa baadaye wa Kamati ya Ukaguzi wa Sheria za Wakati au Ofisi ya Usimamizi wa Ndege</td><td>Kamati ya ukaguzi</td><td>Ndani ya siku 30</td></tr></tbody></table><h2 id="_4-sifa-na-mahitaji-ya-maadili-ya-wafanyakazi-wa-kichunguzi" tabindex="-1">4. Sifa na Mahitaji ya Maadili ya Wafanyakazi wa Kichunguzi <a class="header-anchor" href="#_4-sifa-na-mahitaji-ya-maadili-ya-wafanyakazi-wa-kichunguzi" aria-label="Permalink to &quot;4. Sifa na Mahitaji ya Maadili ya Wafanyakazi wa Kichunguzi&quot;">​</a></h2><p>Watu wanaohusika katika kichunguzi cha kati ya ndege na kurudi nyuma kwa wakati lazima wawe na sifa zifuatazo: miungu ya hatua ya tatu au zaidi ya mfumo wa usimamizi wa sheria za nafasi, kupita ushahidi wa sifa wa kamati ya maadili ya kichunguzi, kukamilisha mafunzo ya kichunguzi ya kuiga yasiyochini ya masaa 100, na hakuna rekodi yoyote ya ukiukaji wa sheria za symbiosis.</p><p>Wafanyakazi wa kichunguzi lazima wafuate mahitaji yafuatayo ya maadili: kuheshimu utamaduni na imani za ustaarabu wa lengwa, kutofanya ubaguzi wa kitamaduni au tathmini ya thamani katika utafiti; kulinda ukamilifu wa eneo la kichunguzi, kutoharibu muundo wa mabaki ili kupata vifaa vya kichunguzi; kurekodi na kuripoti kwa uaminifi matokeo ya kichunguzi, kutobadilisha au kuficha data za kichunguzi; na kufuata kanuni ya &quot;kurudisha maarifa tu&quot;, kutobeba sampuli yoyote ya vifaa kwa kibinafsi nje ya nafasi iliyotengwa.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Muhtasari wa Itifaki ya Kichunguzi ni daraja la sheria lililojengwa na Hengyuanzhou kati ya uchunguzi wa maarifa na ulinzi wa ustaarabu. Kwa vitu vitatu — kioo cha nakala, nafasi iliyotengwa, na kurudisha maarifa tu — kama msaada wa teknolojia, mchakato wa kawaida kama muundo wa uendeshaji, na sifa za wafanyakazi pamoja na mahitaji ya maadili kama dhamana ya kibinadamu, inajenga muundo wa kichunguzi wa &quot;uchafuzi wa chini, ufanisi wa juu, unaoweza kufuatiliwa&quot;. Muundo huu unahakikisha kwamba Hengyuanzhou, wakati anafuata ukweli wa kihistoria, daima anashikilia heshima ya juu zaidi kwa ustaarabu na nyakati zingine.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>85-Mpango wa Kichunguzi cha Njia Nyingine cha Kioo cha Nakala</li><li>86-Mchakato wa Uchafuzi wa Chini katika Nafasi Iliyotengwa</li><li>87-Kanuni ya Kurudisha Maarifa Tu</li></ul>',27)])])}const m=i(t,[["render",h]]);export{s as __pageData,m as default};
